{
  "application": "data-visualization",
  "case_id": "case-event-driven-architecture-panorama",
  "language": "en",
  "style": {
    "theme": "data-dense",
    "audience": "team-internal",
    "tone": "technical, detailed, engineering-focused"
  },
  "goal": [
    {
      "id": "full-event-flow-narrative",
      "insight": "Show the complete event-driven message flow from producer microservices through Kafka topics, Schema Registry validation, consumer microservices, Dead Letter Queues, and retry paths as an integrated architecture diagram"
    },
    {
      "id": "kafka-topic-routing",
      "insight": "Visually emphasize the Kafka topic routing layer as the central hub, clearly showing which microservices publish to and consume from which topics with distinguishable connection paths"
    },
    {
      "id": "error-handling-paths",
      "insight": "Highlight the Dead Letter Queue and retry strategy paths as distinct error-handling flows, visually separating them from the happy-path message routes using color or line style differentiation"
    },
    {
      "id": "monitoring-alert-chain",
      "insight": "Depict the monitoring and alerting chain as a cross-cutting concern that observes multiple components, showing metric collection points and alert trigger connections across the architecture"
    },
    {
      "id": "schema-registry-validation",
      "insight": "Show Schema Registry as a validation checkpoint that interacts with both producers and consumers, emphasizing its role as a gatekeeper in the message serialization pipeline"
    }
  ]
}
